import * as fs from "node:fs";
import * as crypto from "node:crypto";
import * as zlib from "node:zlib";
function main(): void {
  const dir = "/tmp/thaw-bufu8-natives";
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(dir + "/a", "hello world");
  const big = Buffer.alloc(16);
  const view = big.subarray(4, 12);
  const fd = fs.openSync(dir + "/a", "r");
  const n = fs.readSync(fd, view, 0, 5, 6);
  fs.closeSync(fd);
  console.log(n, big.toString("hex"), view.toString("hex"));
  const tail = big.subarray(12);
  crypto.randomFillSync(tail);
  console.log(big.subarray(0, 12).toString("hex"), tail.length);
  const packed = zlib.gzipSync(Buffer.from("abcabcabc"));
  const out = zlib.gunzipSync(packed);
  const out2 = out.subarray(3);
  console.log(out.toString(), out2.toString(), out2.byteOffset - out.byteOffset);
  const digest = crypto.createHash("sha1").update(big.subarray(4, 9)).digest("hex");
  console.log(digest);
  fs.rmSync(dir, { recursive: true });
}
